/*
 * 9box: 9front's commands in one multi-call binary (design/multicall.md).
 *
 * cmds.h, generated by the mkfile from the set, declares each command's
 * renamed main and lists them in cmds[]. The command to run is chosen
 *
 *	by name: the last element of argv[0], for hard links;
 *	by stub: when argv[1] is -! and argv[2] is a file starting
 *		#!/.../9box -!, the last element of argv[2], for stubs;
 *	as 9box CMD ARGS;
 *	and 9box alone lists the commands.
 */
#include <u.h>
#include <libc.h>

typedef struct Cmd Cmd;
struct Cmd
{
	char	*name;
	void	(*main)(int, char**);
};

#include "cmds.h"

static char*
base(char *p)
{
	char *s;

	s = strrchr(p, '/');
	return s != nil ? s+1 : p;
}

/*
 * Whether path is a stub: its first line is #!, a path ending in /9box
 * (or 9box itself), and -!. A command run by name whose first argument
 * happens to be -! (echo -! x) isn't mistaken for one.
 */
static int
isstub(char *path)
{
	char buf[128], *f[4];
	int fd, n;

	fd = open(path, OREAD);
	if(fd < 0)
		return 0;
	n = read(fd, buf, sizeof buf - 1);
	close(fd);
	if(n < 2 || buf[0] != '#' || buf[1] != '!')
		return 0;
	buf[n] = 0;
	if(strchr(buf, '\n') != nil)
		*strchr(buf, '\n') = 0;
	n = tokenize(buf+2, f, nelem(f));
	return n == 2 && strcmp(base(f[0]), "9box") == 0 && strcmp(f[1], "-!") == 0;
}

static void
list(void)
{
	int i;

	for(i = 0; i < nelem(cmds); i++)
		print("%s\n", cmds[i].name);
}

void
main(int argc, char **argv)
{
	char *name;
	Cmd *c;
	int i;

	if(argc < 1)
		exits("no name");
	name = base(argv[0]);
	if(argc > 2 && strcmp(argv[1], "-!") == 0 && isstub(argv[2])){
		/*
		 * #!/bin/9box -! in the file argv[2]: argv[0] is the outermost
		 * script's name, which the command keeps, as it would if it
		 * were the interpreter itself.
		 */
		name = base(argv[2]);
		argv[2] = argv[0];
		argv += 2;
		argc -= 2;
	}else if(strcmp(name, "9box") == 0){
		if(argc < 2){
			list();
			exits(nil);
		}
		argv++;
		argc--;
		name = base(argv[0]);
	}
	/*
	 * A command that initialises a library global would set it for
	 * every command: rc's char *argv0 = "rc". ARGBEGIN sets argv0 only
	 * when it's nil, so it starts nil, as in a separate binary that
	 * doesn't initialise it.
	 */
	argv0 = nil;
	for(i = 0; i < nelem(cmds); i++){
		c = &cmds[i];
		if(strcmp(c->name, name) != 0)
			continue;
		c->main(argc, argv);
		exits(nil);
	}
	fprint(2, "9box: no command %s\n", name);
	exits(smprint("no command %s", name));
}
